"""Helper functions for the MD System Builder GUI tab.This module connects the Streamlit GUI to the scientific backend iniphasimulator."""from __future__ import annotationsfrom pathlib import Pathfrom typing import Anyfrom iphasimulator.build_single_PHA_systems import (    build_dry_PHA,    build_solvated_PHA,    build_solvated_PHA_ions,)from iphasimulator.pha_melt_builder import PHAMeltBuilderdef get_available_built_polymers(    structure_database: str | Path,) -> list[str]:    """    Return the names of available built PHA polymers.    A polymer is included only when its Amber PDB, PRMTOP and RST7 files    are present.    """    structure_database = Path(structure_database)    built_polymers_dir = structure_database / "built_PHAs"    if not built_polymers_dir.exists():        return []    polymer_names: list[str] = []    for polymer_dir in built_polymers_dir.iterdir():        if not polymer_dir.is_dir():            continue        polymer_name = polymer_dir.name        amber_dir = polymer_dir / "amber"        required_files = [            amber_dir / f"{polymer_name}.pdb",            amber_dir / f"{polymer_name}.prmtop",            amber_dir / f"{polymer_name}.rst7",        ]        if all(path.exists() for path in required_files):            polymer_names.append(polymer_name)    return sorted(polymer_names)def build_dry_system(    *,    structure_database: str | Path,    polymer_name: str,    forcefield: str,    box_radius: float,) -> dict[str, Any]:    """Build a dry single-chain PHA system."""    return build_dry_PHA(        polymer_name=polymer_name,        root_dir=structure_database,        forcefield=forcefield,        box_radius=float(box_radius),    )def build_solvated_system(    *,    structure_database: str | Path,    polymer_name: str,    forcefield: str,    water_leaprc: str,    water_box: str,    box_radius: float,) -> dict[str, Any]:    """Build a solvated single-chain PHA system."""    return build_solvated_PHA(        polymer_name=polymer_name,        root_dir=structure_database,        forcefield=forcefield,        water_leaprc=water_leaprc,        water_box=water_box,        box_radius=float(box_radius),    )def build_solvated_ions_system(    *,    structure_database: str | Path,    polymer_name: str,    forcefield: str,    water_leaprc: str,    water_box: str,    box_radius: float,    salt: str,    positive_ion: str,    negative_ion: str,    ion_concentration: float,) -> dict[str, Any]:    """Build a solvated and ionised single-chain PHA system."""    return build_solvated_PHA_ions(        polymer_name=polymer_name,        root_dir=structure_database,        forcefield=forcefield,        water_leaprc=water_leaprc,        water_box=water_box,        box_radius=float(box_radius),        salt=salt,        pos_ion=positive_ion,        neg_ion=negative_ion,        ion_conc=float(ion_concentration),    )def build_melt_system(    *,    structure_database: str | Path,    polymer_names: list[str],    number_of_polymers: list[int],    density: int | float,) -> dict[str, Any]:    """Build an amorphous PHA polymer melt."""    if len(polymer_names) != len(number_of_polymers):        raise ValueError(            "polymer_names and number_of_polymers must have the same length."        )    builder = PHAMeltBuilder(        root_dir=structure_database,    )    return builder.generate_polymer_melt(        polymer_names=polymer_names,        number_of_polymers=[            int(number)            for number in number_of_polymers        ],        density=float(density),    )def get_water_model_settings(    water_model: str,) -> tuple[str, str]:    """    Convert a user-facing water-model name into tleap settings.    Returns    -------    tuple[str, str]        water leaprc and water-box names.    """    settings = {        "TIP3P": (            "water.tip3p",            "TIP3PBOX",        ),    }    try:        return settings[water_model]    except KeyError as error:        raise ValueError(            f"Unsupported water model: {water_model}"        ) from errordef get_salt_name(    positive_ion: str,    negative_ion: str,) -> str:    """Return a readable salt name from the selected ions."""    salts = {        ("K+", "Cl-"): "KCl",        ("Na+", "Cl-"): "NaCl",    }    try:        return salts[            (                positive_ion,                negative_ion,            )        ]    except KeyError as error:        raise ValueError(            "Unsupported ion combination: "            f"{positive_ion} / {negative_ion}"        ) from error